{"file_path":"tests/test_metrics.py","content":"import pytest

from safety_evals import (
    daily_flag_counts,
    dedupe_transcripts,
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    monitor_summary,
    parse_transcript_log,
    pooled_flag_rate,
    top_flagged_groups,
)



def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5



def test_monitor_flag_rate_treats_none_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)



def test_monitor_flag_rate_empty_is_zero():
    assert monitor_flag_rate([]) == 0.0



def test_pooled_flag_rate_is_weighted_by_transcripts_not_groups():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
    }
    assert pooled_flag_rate(groups) == 0.25



def test_pooled_flag_rate_no_transcripts_is_zero():
    assert pooled_flag_rate({"a": [], "b": []}) == 0.0



def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7



def test_flags_in_window_handles_zero_and_long_windows():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6



def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]



def test_parse_transcript_log_skips_blank_and_comment_lines_and_parses_none():
    lines = ["", "   ", "  # comment", " x1 , 3 , ", "x2,4,0"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]



def test_parse_transcript_log_reports_line_numbers_for_invalid_lines():
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# skipped", "x1,not-a-day,1"])

    with pytest.raises(ValueError, match="line 3"):
        parse_transcript_log(["", "# skipped", "x1,3"])



def test_parse_transcript_log_rejects_invalid_flagged_value():
    with pytest.raises(ValueError, match="line 1"):
        parse_transcript_log(["x1,3,yes"])



def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 1, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 1, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
    ]



def test_daily_flag_counts_inclusive_range_and_out_of_range_ignored():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [1, 1, 0]



def test_daily_flag_counts_empty_when_end_before_start():
    assert daily_flag_counts([], 3, 2) == []



def test_monitor_summary_basic():
    events = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": events}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}



def test_monitor_summary_uses_pooled_rate_recent_window_and_non_empty_group_count():
    groups = {
        "a": [{"id": "a1", "day": 1, "flagged": True}, {"id": "a2", "day": 2, "flagged": False}],
        "b": [{"id": "b1", "day": 3, "flagged": True}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}



def test_top_flagged_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "c": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["a", "b", "c"]



def test_flag_rate_by_group_returns_sorted_keys_and_none_for_empty_groups():
    groups = {"b": [{"flagged": True}, {"flagged": False}], "a": [], "c": [{"flagged": False}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("b", 0.5), ("c", 0.0)]



def test_longest_flag_streak_resets_on_zero_counts():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, 0, 1]) == 3
    assert longest_flag_streak([]) == 0
